<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionSnippetVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;

trait SnippetVersionSnippetAttributeHolder
{
    protected SnippetVersionSnippetVO|SnippetRef|null $snippet = null;
    protected bool $snippetAssigned = false;

    public function getSnippetOrCurrent(SnippetVersionSnippetVO $snippet): SnippetVersionSnippetVO
    {
        if ($this->snippetAssigned) {
            \assert(null !== $this->snippet);
            return SnippetVersionSnippetVO::from($this->snippet);
        } else {
            return $snippet;
        }
    }
    public function snippetTryBuildInitial(ConstraintFailList $error): ?SnippetVersionSnippetVO
    {
        return  SnippetVersionSnippetVO::tryFrom($this->snippetAssigned ? $this->snippet : null, $error);
    }
    public function snippet(SnippetVersionSnippetVO|SnippetRef $snippet): static
    {
        $this->snippet = $snippet;
        $this->snippetAssigned = true;
        return $this;
    }
    public function getSnippet(): ?SnippetRef
    {
        return $this->snippet instanceof SnippetVersionSnippetVO ? $this->snippet->value() : $this->snippet;
    }
    public function isSnippetAssigned(): bool
    {
        return $this->snippetAssigned;
    }
    public function writeSnippetTo(mixed $att): void
    {
        if ($this->snippetAssigned) {
            \assert(null !== $this->snippet);
            $att->snippet($this->snippet);
        }
    }
    public function readSnippetFrom(mixed $att): void
    {
        if ($att->isSnippetAssigned()) {
            $snippet = $att->getSnippet();
            \assert(null !== $snippet);
            $this->snippet($snippet);
        }
    }
    public function unsetSnippet(): static
    {
        $this->snippetAssigned = false;
        return $this;
    }
    protected function withDefaultSnippet(): void
    {
    }
    protected function withAssertedSnippetRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->snippetAssigned = $this->snippetAssigned) {
            $value->snippet = SnippetVersionSnippetVO::tryFrom($this->snippet, $errorsList);
        }
    }
}
